/** Public entry point for the data-grid-find-replace add-on — the only module consumers should import from. */

export {
  useDataGridFindReplace,
  type UseDataGridFindReplaceOptions,
  type UseDataGridFindReplaceResult,
} from "./use-data-grid-find-replace";
export { planReplace, type ReplaceOptions, type ReplacePlan, type ReplaceSkipReason, type ReplaceState } from "./plan-replace";

"use client";

import { useEffect, useMemo, useState, type ComponentType } from "react";
import type { DataGridPlugin } from "@/registry/default/components/data-grid/data-grid";
import { FindReplacePanel, type PanelStore } from "./find-replace-panel";
import type { PanelOptions } from "./find-replace-panel";
import type { ReplaceOptions } from "./plan-replace";

export type UseDataGridFindReplaceOptions = Pick<ReplaceOptions, "scope" | "replaceAllLimit"> & {
  /** Shows "Searches loaded rows only" in the panel. Default: on while the grid has a `totalRowCount` or a server `sortMode` or `filterMode`; set `true` for client pages, which hold one page of the rows. */
  showScope?: boolean;
  /**
   * Runs after the plan is built and before it is written. Return the plan to write (it may add, drop, or
   * change patches), or `false` to cancel. The returned plan may hold at most `replaceAllLimit` patches;
   * more cancels the replace. Each patch still goes through the column's `fromText` and `validate`.
   * `signal` aborts when a newer replace starts or the panel closes; a late answer is dropped.
   */
  onReplace?: PanelOptions["onReplace"];
};

export type UseDataGridFindReplaceResult = {
  /** One entry of the grid's `plugins` prop: the panel, the `openFindReplace` and `openFind` commands, and their `ctrl+h` and `mod+f` bindings. */
  plugin: DataGridPlugin<unknown>;
  /** Opens the panel; `"replace"` (default) shows the Replace field, `"find"` hides it until the user expands it. */
  open: (mode?: "find" | "replace") => void;
  close: () => void;
};

function createPanelStore(): PanelStore {
  const listeners = new Set<() => void>();
  let state = { open: false, mode: "replace" as "find" | "replace", openCount: 0 };
  let options: PanelOptions = {};
  return {
    getOptions: () => options,
    setOptions(next) {
      options = next;
    },
    getState: () => state,
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    open(mode) {
      state = { open: true, mode, openCount: state.openCount + 1 };
      listeners.forEach((listener) => listener());
    },
    setMode(mode) {
      if (!state.open || state.mode === mode) return;
      state = { ...state, mode };
      listeners.forEach((listener) => listener());
    },
    close() {
      if (!state.open) return;
      state = { ...state, open: false };
      listeners.forEach((listener) => listener());
    },
  };
}

/**
 * Find and replace for a grid: a panel with Find and Replace fields that shares the quick search
 * (highlights, next/previous) and writes through each column's text codec as one undoable change.
 * Pass `plugin` in the grid's `plugins`; `ctrl+h` opens it with Replace and `mod+f` opens it with Find only.
 */
export function useDataGridFindReplace(options: UseDataGridFindReplaceOptions = {}): UseDataGridFindReplaceResult {
  const [panelStore] = useState(createPanelStore);
  useEffect(() => {
    panelStore.setOptions(options);
  });

  const plugin = useMemo<DataGridPlugin<unknown>>(() => {
    const Mount: ComponentType = function FindReplaceMount() {
      return <FindReplacePanel panelStore={panelStore} />;
    };
    return {
      name: "find-replace",
      Mount,
      commands: {
        openFindReplace: {
          run: (ctx) => panelStore.open(ctx.readOnly ? "find" : "replace"),
        },
        openFind: {
          run: () => panelStore.open("find"),
        },
      },
      keymap: { openFindReplace: ["ctrl+h"], openFind: ["mod+f"] },
    };
  }, [panelStore]);

  return useMemo(
    () => ({ plugin, open: (mode = "replace") => panelStore.open(mode), close: () => panelStore.close() }),
    [plugin, panelStore],
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useId,
  useRef,
  useState,
  useSyncExternalStore,
  type ChangeEvent,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import { CaseSensitive, ChevronDown, ChevronRight, ChevronUp, Replace, ReplaceAll, WholeWord, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { useDebouncedInput } from "@/registry/default/components/gridcn/use-debounce";
import {
  useDataGridApi,
  useDataGridLabels,
  useDataGridReadOnly,
  useDataGridScrollToCellAt,
  useDataGridSearchText,
} from "@/registry/default/components/data-grid/data-grid";
import {
  GRID_ATTR,
  isComposingKey,
  isDev,
  useDataGridInputDebounce,
  useDataGridInstanceId,
  useDataGridSelector,
  useDataGridSearchCapped,
  useDataGridSearchMatches,
  effectivePage,
  fullViewOf,
  pageStartOf,
} from "@/registry/default/components/data-grid/data-grid-sdk";
import { MAX_REPLACE_INPUT_LENGTH, planReplace, resolveReplaceLimit, type ReplaceOptions, type ReplacePlan } from "./plan-replace";

export type PanelStore = {
  getOptions(): PanelOptions;
  setOptions(options: PanelOptions): void;
  getState(): { open: boolean; mode: "find" | "replace"; openCount: number };
  subscribe(listener: () => void): () => void;
  open(mode: "find" | "replace"): void;
  setMode(mode: "find" | "replace"): void;
  close(): void;
};

/** Replace options plus the panel's own: `showScope` forces the loaded-rows note on or off; unset it shows when the result can exceed the loaded rows. */
export type PanelOptions = ReplaceOptions & {
  showScope?: boolean;
  onReplace?: (ctx: { plan: ReplacePlan; signal: AbortSignal }) => ReplacePlan | false | Promise<ReplacePlan | false>;
};

type PanelProps = { panelStore: PanelStore };

type Status = { kind: "replaced"; replaced: number; skipped: number; more: boolean } | { kind: "validating" } | { kind: "cancelled" } | null;


/** True when a row the plan writes is gone or is another object since the plan was built. */
function patchedRowsChanged(before: { data: readonly unknown[]; getRowId: (row: never, index: number) => string }, after: { data: readonly unknown[]; getRowId: (row: never, index: number) => string }, plan: ReplacePlan): boolean {
  const ids = new Set(plan.patches.map((patch) => patch.rowId));
  const rowsBefore = new Map<string, unknown>();
  before.data.forEach((row, index) => {
    if (row === undefined) return;
    const id = before.getRowId(row as never, index);
    if (ids.has(id)) rowsBefore.set(id, row);
  });
  let seen = 0;
  for (let index = 0; index < after.data.length; index++) {
    const row = after.data[index];
    if (row === undefined) continue;
    const id = after.getRowId(row as never, index);
    if (!rowsBefore.has(id)) continue;
    seen++;
    if (rowsBefore.get(id) !== row) return true;
  }
  return seen < rowsBefore.size;
}

function isUsablePlan(plan: unknown, limit: number): plan is ReplacePlan {
  if (typeof plan !== "object" || plan === null) return false;
  const { patches } = plan as { patches?: unknown };
  if (!Array.isArray(patches) || patches.length > limit) return false;
  return patches.every((patch: unknown) => typeof patch === "object" && patch !== null && typeof (patch as { rowId?: unknown }).rowId === "string" && typeof (patch as { columnId?: unknown }).columnId === "string");
}

export function FindReplacePanel({ panelStore }: PanelProps): ReactNode {
  const { open, mode, openCount } = useSyncExternalStore(panelStore.subscribe, panelStore.getState, panelStore.getState);
  if (!open) return null;
  return createPortal(<PanelBody key={openCount} panelStore={panelStore} showReplace={mode === "replace"} />, document.body);
}

function PanelBody({ panelStore, showReplace }: PanelProps & { showReplace: boolean }): ReactNode {
  const api = useDataGridApi();
  const labels = useDataGridLabels().findReplace;
  const readOnly = useDataGridReadOnly();
  const instanceId = useDataGridInstanceId();
  const replaceRowId = useId();
  const matches = useDataGridSearchMatches();
  const capped = useDataGridSearchCapped();
  const searchedText = useDataGridSearchText();
  const scrollToCell = useDataGridScrollToCellAt();
  const resultExceedsLoaded = useDataGridSelector<unknown, boolean>((state) => state.totalRowCount !== undefined || state.sortMode === "server" || state.filterMode === "server");
  const showScope = panelStore.getOptions().showScope ?? resultExceedsLoaded;
  const scopeId = useId();

  const delayMs = useDataGridInputDebounce();
  const [replacement, setReplacement] = useState("");
  const [searchOptions, setSearchOptions] = useState(() => api.store.getState().searchOptions);
  const [storedCursor, setCursor] = useState(0);
  const cursor = Math.max(0, Math.min(storedCursor, matches.length - 1));
  // restart at the first hit during render when the query changes; a data change keeps the position
  const queryKey = `${JSON.stringify(searchedText)}${searchOptions.matchCase}${searchOptions.wholeCell}`;
  const [lastQueryKey, setLastQueryKey] = useState(queryKey);
  if (lastQueryKey !== queryKey) {
    setLastQueryKey(queryKey);
    setCursor(0);
  }
  const [status, setStatus] = useState<Status>(null);
  const [position, setPosition] = useState<{ top: number; end: number; rtl: boolean }>({ top: 8, end: 8, rtl: false });
  const findRef = useRef<HTMLInputElement | null>(null);
  const applyTokenRef = useRef(0);
  const hookControllerRef = useRef<AbortController | null>(null);
  const replacedRef = useRef<Map<string, Set<string>>>(new Map());
  const [openedFromGrid] = useState(() => {
    const grid = document.querySelector(`[${GRID_ATTR.instance}="${CSS.escape(instanceId)}"]`);
    return grid !== null && grid.contains(document.activeElement);
  });

  useEffect(() => {
    findRef.current?.focus();
    findRef.current?.select();
    return () => {
      applyTokenRef.current++;
      hookControllerRef.current?.abort();
    };
  }, []);

  const findInput = useDebouncedInput(searchedText, (text) => api.actions.setSearch(text, searchOptions), { delayMs });
  const find = findInput.inputValue;
  const jumpOnCommitRef = useRef<string | null>(null);

  useEffect(() => {
    replacedRef.current.clear();
    setStatus(null);
    applyTokenRef.current++;
    hookControllerRef.current?.abort();
  }, [searchedText, searchOptions]);

  const closePanel = () => {
    panelStore.close();
    if (openedFromGrid) api.focus();
  };

  useLayoutEffect(() => {
    const place = () => {
      const grid = document.querySelector(`[${GRID_ATTR.instance}="${CSS.escape(instanceId)}"]`);
      if (!grid) return;
      const rect = grid.getBoundingClientRect();
      const top = Math.max(8, rect.top + 8);
      const rtl = getComputedStyle(grid).direction === "rtl";
      const end = Math.max(8, (rtl ? rect.left : window.innerWidth - rect.right) + 24);
      setPosition((current) => (current.top === top && current.end === end && current.rtl === rtl ? current : { top, end, rtl }));
    };
    place();
    window.addEventListener("resize", place);
    window.addEventListener("scroll", place, true);
    // the root settles its `dir` after the first paint
    const grid = document.querySelector(`[${GRID_ATTR.instance}="${CSS.escape(instanceId)}"]`);
    const observer = new MutationObserver(place);
    if (grid) observer.observe(grid, { attributes: true, attributeFilter: ["dir"] });
    return () => {
      window.removeEventListener("resize", place);
      window.removeEventListener("scroll", place, true);
      observer.disconnect();
    };
  }, [instanceId]);

  const runSearch = (text: string, options: { matchCase: boolean; wholeCell: boolean }) => {
    findInput.cancel();
    api.actions.setSearch(text, options);
  };

  const goTo = useCallback(
    (index: number) => {
      const list = api.store.getState().searchMatches;
      if (list.length === 0) return;
      const wrapped = ((index % list.length) + list.length) % list.length;
      setCursor(wrapped);
      const match = list[wrapped]!;
      const col = api.store.getState().visibleColumns.findIndex((c) => c.id === match.columnId);
      if (col === -1) return;
      const state = api.store.getState();
      let row = match.row;
      if (state.pageSize !== null) {
        const page = Math.floor(match.row / state.pageSize) + 1;
        if (effectivePage(state.page, fullViewOf(state.viewIndex).length, state.pageSize) !== page) api.actions.setPage(page);
        if (api.store.getState().page !== page) return;
        row = match.row - pageStartOf(api.store.getState().viewIndex);
      }
      api.actions.setActiveCellAt({ col, row });
      scrollToCell({ col, row });
    },
    [api, scrollToCell],
  );

  // A controlled parent applies the committed text later, so the first match is known only once searchedText has caught up.
  useEffect(() => {
    if (jumpOnCommitRef.current === null || jumpOnCommitRef.current !== searchedText) return;
    jumpOnCommitRef.current = null;
    goTo(0);
  }, [searchedText, matches, goTo]);

  const onFindChange = (event: ChangeEvent<HTMLInputElement>) => {
    setStatus(null);
    applyTokenRef.current++;
    hookControllerRef.current?.abort();
    replacedRef.current.clear();
    jumpOnCommitRef.current = null;
    findInput.inputProps.onChange(event);
  };

  const toggle = (key: "matchCase" | "wholeCell") => {
    const next = { ...searchOptions, [key]: !searchOptions[key] };
    setSearchOptions(next);
    setStatus(null);
    replacedRef.current.clear();
    runSearch(find, next);
  };

  const canReplace = !readOnly && find.trim() !== "";

  const refOfMatch = (): { rowId: string; columnId: string } | null => {
    const s = api.store.getState();
    const active = s.activeCell;
    const activeColumnId = active ? s.visibleColumns[active.col]?.id : undefined;
    const start = pageStartOf(s.viewIndex);
    const onActive = active && s.searchMatches.find((m) => m.row === active.row + start && m.columnId === activeColumnId);
    const match = onActive || s.searchMatches[cursor];
    if (!match) return null;
    const dataIndex = fullViewOf(s.viewIndex)[match.row];
    const row = dataIndex === undefined ? undefined : s.data[dataIndex];
    if (dataIndex === undefined || row === undefined) return null;
    return { rowId: s.getRowId(row, dataIndex), columnId: match.columnId };
  };

  const apply = (only: { rowId: string; columnId: string } | undefined) => {
    const s = api.store.getState();
    if (s.readOnly || s.editing !== null || find.trim() === "") return;
    const replaced = replacedRef.current;
    const skip = only ? undefined : (ref: { rowId: string; columnId: string }) => replaced.get(ref.rowId)?.has(ref.columnId) === true;
    const plan = planReplace(s, find, replacement, { ...panelStore.getOptions(), ...searchOptions, only, skip });
    const run = (finalPlan: ReplacePlan) => {
      if (!only) {
        if (!finalPlan.remaining) replaced.clear();
        else for (const { rowId, columnId } of finalPlan.patches) replaced.set(rowId, (replaced.get(rowId) ?? new Set()).add(columnId));
      }
      const verdict = finalPlan.patches.length === 0 ? null : api.actions.updateCells(finalPlan.patches, { source: "replace", reorder: "defer" });
      const token = ++applyTokenRef.current;
      const finish = (settled: { applied: number; skipped: readonly unknown[] } | null) => {
        setStatus({
          kind: "replaced",
          replaced: settled?.applied ?? 0,
          skipped: finalPlan.skipped.length + (settled?.skipped.length ?? 0),
          more: finalPlan.remaining,
        });
        runSearch(find, searchOptions);
        if (only) {
          const left = api.store.getState().searchMatches.length;
          if (left > 0) goTo(Math.min(cursor, left - 1));
        }
      };
      if (verdict?.pending) {
        setStatus({ kind: "validating" });
        void verdict.settled?.then(
          (settled) => {
            if (token === applyTokenRef.current) finish(settled);
          },
          () => {
            if (token === applyTokenRef.current) finish(null);
          },
        );
        return;
      }
      finish(verdict);
    };

    const onReplace = panelStore.getOptions().onReplace;
    if (!onReplace) {
      run(plan);
      return;
    }
    hookControllerRef.current?.abort();
    const controller = new AbortController();
    hookControllerRef.current = controller;
    const hookToken = ++applyTokenRef.current;
    setStatus({ kind: "validating" });
    const limit = resolveReplaceLimit(panelStore.getOptions().replaceAllLimit);
    const current = () => hookToken === applyTokenRef.current && !controller.signal.aborted;
    void Promise.resolve()
      .then(() => onReplace({ plan, signal: controller.signal }))
      .then(
        (result) => {
          if (!current()) return;
          const latest = api.store.getState();
          if (latest.readOnly || latest.editing !== null || result === false) {
            setStatus({ kind: "cancelled" });
            return;
          }
          if (!isUsablePlan(result, limit)) {
            if (isDev()) console.warn("[data-grid-find-replace] onReplace returned no plan or more patches than replaceAllLimit; the replace is cancelled");
            setStatus({ kind: "cancelled" });
            return;
          }
          if (latest.data !== s.data && patchedRowsChanged(s, latest, result)) {
            setStatus({ kind: "cancelled" });
            return;
          }
          run({ patches: result.patches, skipped: Array.isArray(result.skipped) ? result.skipped : [], remaining: result.remaining === true });
        },
        (error: unknown) => {
          if (!current()) return;
          if (isDev()) console.warn("[data-grid-find-replace] onReplace threw; the replace is cancelled", error);
          setStatus({ kind: "cancelled" });
        },
      );
  };

  const replaceOne = () => {
    const ref = refOfMatch();
    if (ref) apply(ref);
  };

  const onKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    event.stopPropagation();
    if (isComposingKey(event)) return;
    if ((event.ctrlKey || event.metaKey) && !event.altKey && !event.shiftKey && event.key.toLowerCase() === "f") {
      event.preventDefault();
      findRef.current?.focus();
      findRef.current?.select();
      return;
    }
    if (event.key === "Escape") {
      event.preventDefault();
      findInput.cancel();
      closePanel();
    }
  };

  const onFindKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (event.key !== "Enter" || isComposingKey(event)) return;
    event.preventDefault();
    if (findInput.inputValue !== searchedText) {
      jumpOnCommitRef.current = findInput.inputValue;
      findInput.flush();
    } else goTo(cursor + (event.shiftKey ? -1 : 1));
  };

  const onReplaceKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (event.key !== "Enter" || isComposingKey(event) || !canReplace) return;
    event.preventDefault();
    if (event.ctrlKey || event.metaKey) apply(undefined);
    else replaceOne();
  };

  const hasMatches = matches.length > 0;
  const noResults = status === null && find.trim() !== "" && searchedText === find && !hasMatches;
  const statusText = (() => {
    if (status?.kind === "validating") return labels.validating;
    if (status?.kind === "cancelled") return labels.replaceCancelled;
    if (status?.kind === "replaced") return status.more ? `${labels.replaced(status.replaced, status.skipped)}. ${labels.moreRemain}` : labels.replaced(status.replaced, status.skipped);
    if (find.trim() === "") return labels.typeToSearch;
    if (searchedText !== find) return "";
    return hasMatches ? labels.position(cursor + 1, matches.length, capped) : labels.noMatches;
  })();

  const optionToggle = (key: "matchCase" | "wholeCell", label: string, icon: ReactNode) => (
    <Button
      type="button"
      variant={searchOptions[key] ? "default" : "ghost"}
      size="icon"
      title={label}
      aria-label={label}
      aria-pressed={searchOptions[key]}
      data-state={searchOptions[key] ? "on" : "off"}
      onClick={() => toggle(key)}
      className={cn("shrink-0", searchOptions[key] ? "forced-colors:border-2 forced-colors:border-[Highlight] forced-colors:bg-[Highlight] forced-colors:text-[HighlightText]" : "text-muted-foreground")}
    >
      {icon}
    </Button>
  );

  // Not the Popover primitive: the panel docks to the grid corner without a trigger and keeps its own focus and Escape rules.
  return (
    <div
      role="dialog"
      aria-label={labels.dialogLabel}
      {...{ [GRID_ATTR.findReplacePanel]: "", [GRID_ATTR.keepFocus]: "" }}
      onKeyDown={onKeyDown}
      onCopy={(event) => event.stopPropagation()}
      onCut={(event) => event.stopPropagation()}
      onPaste={(event) => event.stopPropagation()}
      // body-portaled: physical offsets and `dir` follow the grid, not the page
      dir={position.rtl ? "rtl" : "ltr"}
      style={{ position: "fixed", top: position.top, ...(position.rtl ? { left: position.end } : { right: position.end }), zIndex: 50, maxWidth: `calc(100vw - ${position.end}px - 8px)` }}
      className="flex w-80 flex-col gap-1 rounded-lg bg-popover p-2 text-sm text-popover-foreground shadow-md ring-1 ring-foreground/10"
    >
      <div className="flex items-center gap-1">
        {!readOnly && (
          <Button
            type="button"
            variant="ghost"
            size="icon-sm"
            className="size-8 shrink-0"
            aria-label={labels.toggleReplace}
            aria-expanded={showReplace}
            aria-controls={replaceRowId}
            onClick={() => panelStore.setMode(showReplace ? "find" : "replace")}
          >
            <ChevronRight className={showReplace ? "rotate-90" : "rtl:rotate-180"} />
          </Button>
        )}
        <div data-find-field="" className="flex h-9 min-w-0 flex-1 items-center rounded-md border border-input bg-transparent pe-0.5 focus-within:ring-2 focus-within:ring-ring/50">
          <Input
            ref={findRef}
            maxLength={MAX_REPLACE_INPUT_LENGTH}
            {...findInput.inputProps}
            onChange={onFindChange}
            onKeyDown={onFindKeyDown}
            aria-label={labels.findLabel}
            aria-describedby={showScope ? scopeId : undefined}
            placeholder={labels.findLabel}
            className="h-8 min-w-0 flex-1 border-0 bg-transparent shadow-none focus-visible:ring-0"
          />
          {optionToggle("matchCase", labels.matchCase, <CaseSensitive />)}
          {optionToggle("wholeCell", labels.wholeCell, <WholeWord />)}
        </div>
        <Button type="button" variant="ghost" size="icon-sm" className="size-8 shrink-0" aria-label={labels.previous} title={labels.previousTitle} disabled={!hasMatches} onClick={() => goTo(cursor - 1)}>
          <ChevronUp />
        </Button>
        <Button type="button" variant="ghost" size="icon-sm" className="size-8 shrink-0" aria-label={labels.next} title={labels.nextTitle} disabled={!hasMatches} onClick={() => goTo(cursor + 1)}>
          <ChevronDown />
        </Button>
        <Button type="button" variant="ghost" size="icon-sm" className="size-8 shrink-0" aria-label={labels.close} title={labels.close} onClick={closePanel}>
          <X />
        </Button>
      </div>
      {showReplace && (
        <div id={replaceRowId} className="flex items-center gap-1">
          {!readOnly && <span aria-hidden="true" className="size-8 shrink-0" />}
          <Input
            value={replacement}
            maxLength={MAX_REPLACE_INPUT_LENGTH}
            onChange={(event) => {
              setReplacement(event.target.value);
              replacedRef.current.clear();
              applyTokenRef.current++;
              hookControllerRef.current?.abort();
            }}
            onKeyDown={onReplaceKeyDown}
            aria-label={labels.replaceLabel}
            placeholder={labels.replaceLabel}
            disabled={readOnly}
            className="h-9 min-w-0 flex-1"
          />
          <Button type="button" variant="ghost" size="icon-sm" className="size-8 shrink-0" aria-label={labels.replace} title={labels.replace} disabled={!canReplace || !hasMatches} onClick={replaceOne}>
            <Replace />
          </Button>
          <Button type="button" variant="ghost" size="icon-sm" className="size-8 shrink-0" aria-label={labels.replaceAll} title={labels.replaceAll} disabled={!canReplace || !hasMatches} onClick={() => apply(undefined)}>
            <ReplaceAll />
          </Button>
        </div>
      )}
      {showScope && (
        <p id={scopeId} className="px-1 text-xs text-muted-foreground">
          {labels.scopeLoadedRows}
        </p>
      )}
      <div role="status" aria-live="polite" title={statusText} className={cn("h-5 truncate px-1 font-mono text-xs tabular-nums", noResults ? "text-destructive" : "text-muted-foreground")}>
        {statusText}
      </div>
    </div>
  );
}

import { type AnyColumnDef, type CellPatch, type CellRef, type SearchOptions } from "@/registry/default/components/data-grid/data-grid";
import { createTextMatcher, fullViewOf, selectionContainsCell, toSafeText, type DataGridReadState } from "@/registry/default/components/data-grid/data-grid-sdk";

/** Longest find or replacement text; longer input is cut. */
export const MAX_REPLACE_INPUT_LENGTH = 1_000;
/** Longest text one replaced cell may reach. */
export const MAX_REPLACED_CELL_LENGTH = 100_000;
const DEFAULT_REPLACE_ALL_LIMIT = 10_000;
const MAX_REPLACE_ALL_LIMIT = 100_000;

/** The most cells one plan may target after `replaceAllLimit` is applied: default 10,000, clamped to 1..100,000. */
export function resolveReplaceLimit(replaceAllLimit: number | undefined): number {
  return Math.min(Math.max(Math.floor(replaceAllLimit ?? DEFAULT_REPLACE_ALL_LIMIT) || 1, 1), MAX_REPLACE_ALL_LIMIT);
}

/** What `planReplace` reads from the grid. */
export type ReplaceState = Pick<DataGridReadState, "data" | "viewIndex" | "visibleColumns" | "cellTypes" | "getRowId" | "selection">;

export type ReplaceOptions = SearchOptions & {
  /** `"view"` (default) covers every visible column of the rows in the view; `"selection"` covers the selected cells. */
  scope?: "view" | "selection";
  /** Most cells one plan targets; default 10,000, clamped to 1..100,000. */
  replaceAllLimit?: number;
  /** Leaves out the cells it returns `true` for; a continuation passes the cells an earlier plan replaced. */
  skip?: (ref: CellRef) => boolean;
};

export type ReplaceSkipReason = "readonly" | "unparseable" | "too-long" | "no-occurrence";

export type ReplacePlan = {
  patches: CellPatch[];
  skipped: { ref: CellRef; reason: ReplaceSkipReason }[];
  /** True when the limit stopped the scan and more cells match. */
  remaining: boolean;
};

type ColumnPlan = {
  column: AnyColumnDef;
  readValue: (row: unknown) => unknown;
  readText: (value: unknown) => string;
  fromText: (text: string) => unknown;
  isEmpty: (value: unknown) => boolean;
};

function planColumn(column: AnyColumnDef, cellTypes: ReplaceState["cellTypes"]): ColumnPlan | null {
  const cellType = cellTypes[column.type ?? "text"];
  if (!cellType || cellType.activate) return null;
  const toText = cellType.toSearchText ?? cellType.toText;
  const options = column.options;
  const { accessorFn, accessorKey } = column;
  return {
    column,
    readValue: accessorFn ? (row) => accessorFn(row) : (row) => (row as Record<string, unknown>)[accessorKey as string],
    readText: (value) => {
      if (value == null) return "";
      try {
        return toSafeText(toText(value, options));
      } catch {
        return toSafeText(value);
      }
    },
    fromText: (text) => cellType.fromText(text, options),
    isEmpty: (value) => cellType.isEmpty(value),
  };
}

function isReadOnly(column: AnyColumnDef, row: unknown): boolean {
  if (!column.setValue && !column.accessorKey) return true;
  return typeof column.readOnly === "function" ? column.readOnly(row) : Boolean(column.readOnly);
}

/** Lowercases `text` for matching; `sourceAt` maps each folded index to its source index when lowercasing changed the length. */
function foldText(text: string, matchCase: boolean): { folded: string; sourceAt: number[] | null } {
  const lower = matchCase ? text : text.toLowerCase();
  if (lower.length === text.length) return { folded: lower, sourceAt: null };
  const parts: string[] = [];
  const sourceAt: number[] = [];
  for (let i = 0; i < text.length; ) {
    const char = String.fromCodePoint(text.codePointAt(i)!);
    const lowered = char.toLowerCase();
    parts.push(lowered);
    for (let k = 0; k < lowered.length; k++) sourceAt.push(i);
    i += char.length;
  }
  return { folded: parts.join(""), sourceAt };
}

/** Replaces every occurrence of `needle` in `text`; `null` when the result would pass the cell cap, `found: false` when no whole-character occurrence exists. */
function replaceOccurrences(text: string, needle: string, replacement: string, matchCase: boolean): { text: string; found: boolean } | null {
  const target = matchCase ? needle : needle.toLowerCase();
  const { folded, sourceAt } = foldText(text, matchCase);
  const startsOnChar = (at: number) => at === 0 || at === folded.length || sourceAt![at - 1] !== sourceAt![at];
  const spans: [number, number][] = [];
  let projected = text.length;
  for (let from = 0; ; ) {
    const at = folded.indexOf(target, from);
    if (at === -1) break;
    const end = at + target.length;
    if (sourceAt && !(startsOnChar(at) && startsOnChar(end))) {
      from = at + 1;
      continue;
    }
    const start = sourceAt ? sourceAt[at]! : at;
    const stop = sourceAt ? (end === folded.length ? text.length : sourceAt[end]!) : end;
    spans.push([start, stop]);
    projected += replacement.length - (stop - start);
    if (projected > MAX_REPLACED_CELL_LENGTH) return null;
    from = end;
  }
  let out = "";
  let cursor = 0;
  for (const [start, stop] of spans) {
    out += text.slice(cursor, start) + replacement;
    cursor = stop;
  }
  return { text: out + text.slice(cursor), found: spans.length > 0 };
}

/**
 * Plans a replace over the grid: the cells whose search text matches `find`, each with the value
 * its type parses from the replaced text. Pure — the caller writes the patches. Hole rows, hidden
 * columns, and filtered-out rows never appear; read-only cells and results the type cannot parse
 * are reported in `skipped`.
 */
export function planReplace(
  state: ReplaceState,
  find: string,
  replacement: string,
  options: ReplaceOptions & { only?: CellRef } = {},
): ReplacePlan {
  const plan: ReplacePlan = { patches: [], skipped: [], remaining: false };
  const needle = find.slice(0, MAX_REPLACE_INPUT_LENGTH).trim();
  const isMatch = createTextMatcher(needle, options);
  if (isMatch === null) return plan;

  const { matchCase = false, wholeCell = false, scope = "view", only, skip } = options;
  const to = replacement.slice(0, MAX_REPLACE_INPUT_LENGTH);
  const limit = resolveReplaceLimit(options.replaceAllLimit);
  const columns = state.visibleColumns.map((column) => planColumn(column, state.cellTypes));

  const visit = (colIndex: number, rowId: string, row: unknown): boolean => {
    const entry = columns[colIndex];
    if (!entry) return true;
    const text = entry.readText(entry.readValue(row));
    if (!isMatch(text)) return true;
    const ref = { rowId, columnId: entry.column.id };
    if (skip?.(ref)) return true;
    if (isReadOnly(entry.column, row)) {
      plan.skipped.push({ ref, reason: "readonly" });
      return true;
    }
    const replaced = wholeCell ? { text: to, found: true } : replaceOccurrences(text, needle, to, matchCase);
    if (replaced === null) {
      plan.skipped.push({ ref, reason: "too-long" });
      return true;
    }
    if (!replaced.found) {
      plan.skipped.push({ ref, reason: "no-occurrence" });
      return true;
    }
    const next = replaced.text;
    if (next === text) return true;
    const value = entry.fromText(next);
    if (next.trim() !== "" && entry.isEmpty(value)) {
      plan.skipped.push({ ref, reason: "unparseable" });
      return true;
    }
    if (plan.patches.length >= limit) {
      plan.remaining = true;
      return false;
    }
    plan.patches.push({ ...ref, value });
    return true;
  };

  const { data } = state;
  const onlySelected = scope === "selection";
  const viewIndex = onlySelected ? state.viewIndex : fullViewOf(state.viewIndex);
  for (let viewRow = 0; viewRow < viewIndex.length; viewRow++) {
    const dataIndex = viewIndex[viewRow]!;
    const row = data[dataIndex];
    if (row === undefined) continue;
    const rowId = state.getRowId(row, dataIndex);
    if (only && only.rowId !== rowId) continue;
    for (let col = 0; col < columns.length; col++) {
      if (only && only.columnId !== state.visibleColumns[col]!.id) continue;
      if (onlySelected && !selectionContainsCell(state.selection, { row: viewRow, col })) continue;
      if (!visit(col, rowId, row)) return plan;
    }
    if (only) return plan;
  }
  return plan;
}
